#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <ctime>
#include <iomanip>

#ifdef _WIN32
    #include <windows.h>
    #define CLEAR "cls"
#else
    #include <unistd.h>
    #define CLEAR "clear"
#endif

using namespace std;

struct Item {
    string name;
    double price;
};

struct Case {
    string name;
    double cost;
    vector<Item> items;
};

double randomPrice(double min, double max) {
    return ((rand() % 1000) / 1000.0) * (max - min) + min;
}

void waitForEnter() {
    cout << "\nPress Enter to continue...";
    cin.ignore();
    cin.get();
    system(CLEAR);
}

