        {"FAMAS | Cyanospatter", randomPrice(0.10, 0.30)},
        {"Glock-18 | Groundwater", randomPrice(0.05, 0.25)},
        {"Tec-9 | VariCamo", randomPrice(0.01, 0.20)},
        {"P90 | Scorched", randomPrice(0.10, 0.25)},
        {"Nova | Polar Mesh", randomPrice(0.05, 0.20)}
    };

    vector<Item> moderateItems = {
        {"AK-47 | Elite Build", randomPrice(0.50, 1.20)},
        {"M4A1-S | Nitro", randomPrice(0.40, 0.90)},
        {"AWP | Acheron", randomPrice(0.35, 0.75)},
